INSERT INTO respuestas (intent_id, texto_respuesta, activa, fecha_actualizacion, actualizado_por) VALUES ((SELECT intent_id FROM intenciones WHERE nombre_intent = 'info_admisiones'), 'El proceso de admisión lo coordina la Dirección de Admisiones. En general: 1) revisa la oferta de programas y sus requisitos en el portal institucional, 2) diligencia la inscripción en línea dentro de las fechas del calendario de admisiones vigente, 3) paga el derecho de inscripción y 4) consulta los resultados en la fecha publicada. Más información: https://www.uptc.edu.co', TRUE, CURRENT_TIMESTAMP, NULL);
